<template>
  <teleport to="body"><div class="settings-backdrop" @click.self="$emit('close')"><section class="settings-panel glass-panel" role="dialog" aria-modal="true" aria-labelledby="settings-title">
    <header><div><span class="eyebrow">PERSONALIZA TU PRÁCTICA</span><h2 id="settings-title">Configuración</h2></div><button class="close-settings" @click="$emit('close')" aria-label="Cerrar configuración">×</button></header>
    <div class="gemini-title"><div class="gemini-mark">✦</div><div><h3>Revisión con Gemini</h3><p>Una segunda mirada a tus respuestas abiertas.</p></div><label class="switch"><input type="checkbox" v-model="enabled" :disabled="busy"><span></span><b>{{ enabled?'Activada':'Opcional' }}</b></label></div>
    <p class="settings-description">Conecta tu propia clave para revisar razonamientos, redacciones y expresiones equivalentes. Sin Gemini puedes seguir comparando tus respuestas con la solución.</p>
    <label for="gemini-key" class="field-label">Tu API key</label><div class="key-field"><input id="gemini-key" ref="keyInput" v-model="apiKey" :type="showKey?'text':'password'" :disabled="busy" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Pega tu clave de Google AI Studio"><button type="button" @click="showKey=!showKey" :aria-label="showKey?'Ocultar clave':'Mostrar clave'">{{ showKey?'Ocultar':'Mostrar' }}</button></div>
    <p class="privacy-copy">La clave se guarda sólo en este navegador. Al revisar, el enunciado, tu respuesta y la rúbrica se envían directamente a Google. Las solicitudes utilizan la cuota de tu cuenta.</p>
    <div class="connection-row"><button class="btn btn-secondary" @click="testConnection" :disabled="busy||!apiKey.trim()">{{ busy?'Consultando…':'Probar conexión y listar modelos' }}</button><span v-if="verified" class="connected-label">✓ Conexión comprobada</span></div>
    <label for="gemini-model" class="field-label">Modelo para la revisión</label><select id="gemini-model" v-model="model" :disabled="busy||!availableModels.length"><option value="">{{ availableModels.length?'Selecciona un modelo':'Consulta los modelos con tu clave' }}</option><option v-for="item in availableModels" :key="item.name" :value="item.name">{{ item.displayName }}</option></select>
    <p v-if="model&&!availableModels.length" class="privacy-copy">Modelo guardado: {{ model.replace('models/','') }}. Comprueba la conexión para actualizar la lista.</p>
    <p class="model-note">La lista se obtiene de tu cuenta. Se priorizan modelos Flash estables para esta tarea; puedes elegir otro disponible.</p>
    <p v-if="notice" role="status" class="settings-notice" :class="{error:noticeIsError}">{{ notice }}</p>
    <footer><button class="btn delete-key" :disabled="busy||!hasSavedKey" @click="deleteKey">Borrar clave</button><div><button class="btn btn-secondary" :disabled="busy" @click="$emit('close')">Cerrar</button><button class="btn btn-primary" :disabled="busy" @click="save">Guardar configuración</button></div></footer>
  </section></div></teleport>
</template>
<script>
const {ref,computed,onMounted,onUnmounted,watch}=Vue;
export default{
 emits:['close'],
 setup(_, {emit}){
  const gemini=window.useGemini(),saved=gemini.config.value;
  const apiKey=ref(saved.apiKey),enabled=ref(saved.enabled),model=ref(saved.model),showKey=ref(false),busy=ref(false),verified=ref(false),notice=ref(''),noticeIsError=ref(false),keyInput=ref(null);
  const availableModels=ref([...gemini.modelsForKey(saved.apiKey)]);const hasSavedKey=computed(()=>Boolean(gemini.config.value.apiKey));let controller=null,active=true;
  watch(apiKey,()=>{verified.value=false;availableModels.value=[];model.value='';if(apiKey.value!==gemini.config.value.apiKey)notice.value='';});
  function message(text,error=false){notice.value=text;noticeIsError.value=error;}
  async function testConnection(){
   if(busy.value)return;busy.value=true;notice.value='';controller=new AbortController();
   try{const models=await gemini.listModels(apiKey.value,controller.signal);if(!active)return;availableModels.value=models;if(!models.some(m=>m.name===model.value))model.value=models[0]?.name||'';verified.value=true;message(`${models.length} modelos de texto disponibles. Guarda para aplicar tu selección.`);}
   catch(error){if(active){verified.value=false;message(error.message,true);}}
   finally{if(active)busy.value=false;}
  }
  function save(){try{gemini.save({enabled:enabled.value,apiKey:apiKey.value,model:model.value});showKey.value=false;message(enabled.value?'Gemini está listo para las respuestas abiertas.':'Configuración guardada. La revisión manual sigue disponible.');}catch(error){message(error.message,true);}}
  function deleteKey(){try{gemini.clear();apiKey.value='';model.value='';enabled.value=false;availableModels.value=[];verified.value=false;showKey.value=false;message('Clave eliminada de este navegador. Gemini quedó desactivado.');}catch(error){message(error.message,true);}}
  const escape=e=>{if(e.key==='Escape'&&!busy.value)emit('close');};
  onMounted(()=>{document.addEventListener('keydown',escape);keyInput.value?.focus();});onUnmounted(()=>{active=false;controller?.abort();document.removeEventListener('keydown',escape);});
  return{apiKey,enabled,model,showKey,busy,verified,notice,noticeIsError,keyInput,availableModels,hasSavedKey,testConnection,save,deleteKey};
 }
};
</script>
<style scoped>
.settings-backdrop{position:fixed;inset:0;z-index:300;display:flex;align-items:center;justify-content:center;background:rgba(15,23,42,.5);backdrop-filter:blur(9px);padding:1rem;box-sizing:border-box}.settings-panel{width:100%;max-width:620px;max-height:92vh;overflow:auto;padding:2rem;border-radius:24px;background:var(--glass-bg,#fff);color:var(--text-main);box-sizing:border-box;box-shadow:0 24px 100px rgba(0,0,0,.25)}header,footer,.gemini-title,.connection-row{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}header{margin-bottom:1.5rem}.eyebrow{font-size:.65rem;letter-spacing:.12em;font-weight:800;color:var(--primary)}h2{margin:.2rem 0;font-size:1.8rem}.close-settings{background:transparent;border:0;font-size:1.8rem;color:var(--text-muted);cursor:pointer;line-height:1;width:36px;height:36px}.gemini-title{justify-content:flex-start;gap:.8rem}.gemini-mark{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(135deg,rgba(79,70,229,.18),rgba(16,185,129,.15));color:var(--primary);font-size:1.6rem}.gemini-title h3{margin:0;font-size:1.1rem}.gemini-title p{margin:.2rem 0 0;font-size:.82rem;color:var(--text-muted)}.switch{margin-left:auto;display:flex;align-items:center;gap:.5rem;cursor:pointer;font-size:.75rem}.switch input{position:absolute;opacity:0}.switch span{width:38px;height:22px;background:rgba(100,116,139,.3);border-radius:20px;position:relative}.switch span:before{content:'';position:absolute;left:3px;top:3px;width:16px;height:16px;border-radius:50%;background:white;transition:.2s}.switch input:checked+span{background:var(--primary)}.switch input:checked+span:before{transform:translateX(16px)}.switch input:focus-visible+span{outline:2px solid var(--primary);outline-offset:3px}.settings-description{font-size:.9rem;line-height:1.6;color:var(--text-muted);margin:1.2rem 0}.field-label{display:block;font-weight:700;font-size:.85rem;margin:1rem 0 .45rem}.key-field{display:flex;border:1px solid var(--glass-border);border-radius:12px;background:var(--calc-tab-bg-active,white);overflow:hidden}.key-field input{border:0;flex:1;min-width:0;background:transparent;padding:.85rem;font:inherit;color:var(--text-main)}.key-field button{border:0;background:transparent;color:var(--primary);padding:0 .85rem;font:inherit;font-size:.8rem;cursor:pointer}select{width:100%;padding:.8rem;border:1px solid var(--glass-border);border-radius:12px;background:var(--calc-tab-bg-active,white);color:var(--text-main);font:inherit;font-size:.88rem}.privacy-copy,.model-note{font-size:.76rem;line-height:1.55;color:var(--text-muted);margin:.6rem 0 1rem}.connection-row{margin:1rem 0;font-size:.78rem}.connection-row .btn{font-size:.8rem;padding:.65rem .8rem}.connected-label{color:var(--secondary);font-weight:700}.settings-notice{padding:.8rem;border-radius:10px;background:rgba(16,185,129,.09);color:var(--text-main);font-size:.83rem;line-height:1.5}.settings-notice.error{background:rgba(245,158,11,.1)}footer{border-top:1px solid var(--glass-border);padding-top:1.1rem;margin-top:1.2rem}footer>div{display:flex;gap:.5rem}footer .btn{font-size:.8rem;padding:.7rem .85rem}.delete-key{color:var(--danger);background:transparent}.settings-panel :focus-visible{outline:2px solid var(--primary);outline-offset:2px}@media(max-width:520px){.settings-panel{padding:1.2rem}.switch{margin-left:0}.gemini-title>div:nth-child(2){flex:1}footer>div{width:100%}footer>div>.btn{flex:1}}
</style>
